// Cria o ID do job e lê as opções enviadas pelo site (multipart: file + dryRun)
const body = $('Webhook Upload').first().json.body || {};
const dryRun = String(body.dryRun || '').toLowerCase() === 'true';
const jobId = 'imp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const item = $input.first();
return [{ json: { jobId, dryRun, recebidoEm: new Date().toISOString() }, binary: item.binary }];

// Transforma as linhas da planilha em itens padronizados (cabeçalhos sem acento/maiúscula)
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const out = [];
let n = 1; // linha 1 = cabeçalho
for (const it of $input.all()) {
  n++;
  const cells = {};
  let temAlgo = false;
  for (const [k, v] of Object.entries(it.json)) {
    if (k === '' || k == null) continue;
    let val = v;
    if (val instanceof Date) val = val.toISOString().slice(0, 10);
    if (typeof val === 'number' && Number.isFinite(val)) val = Number.isInteger(val) ? BigInt(val).toString() : String(val);
    val = (val ?? '').toString().trim();
    cells[norm(k)] = val;
    if (val !== '') temAlgo = true;
  }
  if (!temAlgo) continue; // ignora linhas totalmente vazias
  out.push({ json: { _linha: n, cells } });
}
if (!out.length) throw new Error('A planilha não tem nenhuma linha preenchida.');
return out;

// Cruza cada linha com Pipelines/Etapas, Tags e Campos personalizados do CRM.
// Linhas com problema NÃO vão para o CRM e aparecem no relatório.
const CFG = {
  pipelinePadrao: '',   // usado quando a planilha não tem a coluna "pipeline" (nome exato)
  etapaPadrao: '',      // usado quando a planilha não tem a coluna "etapa do funil"
  userIdPadrao: '',     // usado quando a planilha não tem "atendente vinculado" (ID do usuário)
  ddiPadrao: '55',      // acrescentado quando o número vier só com DDD+número
  bloquearDuplicadasNoArquivo: true,
};
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const ALIAS = {
  nome: ['nome', 'nome contato', 'nome do contato', 'contato', 'cliente'],
  phone: ['numero', 'telefone', 'whatsapp', 'celular', 'phone', 'fone'],
  pipeline: ['pipeline', 'funil'],
  etapa: ['etapa do funil', 'etapa', 'coluna', 'estagio'],
  user: ['atendente vinculado', 'atendente', 'userid', 'id atendente', 'id do atendente', 'responsavel'],
  empresa: ['empresa'],
  email: ['email', 'e-mail'],
  tag: ['tag de negociacao', 'tag', 'tags', 'etiquetas', 'etiqueta'],
  motivo: ['motivo de perda', 'motivo da perda'],
};
const usados = new Set(Object.values(ALIAS).flat());
const pick = (cells, list) => { for (const a of list) if (cells[a] !== undefined && cells[a] !== '') return cells[a]; return ''; };

const dryRun = !!$('Criar job').first().json.dryRun;
const pipelines = $('GET Pipelines').all().map(i => i.json).filter(j => j && j.id);
const tags = $('GET Tags').all().map(i => i.json).filter(j => j && j.id);
const campos = $input.all().map(i => i.json).filter(j => j && j.id);
const camposAtivos = campos.filter(c => !c.archived);

const ignoradas = new Set();
const vistos = new Map();
const out = [];

for (const it of $('Normalizar').all()) {
  const { _linha, cells } = it.json;
  const erros = [];
  const p = {};

  // nome
  p.contactName = pick(cells, ALIAS.nome);
  if (!p.contactName) erros.push('nome vazio');

  // telefone
  let tel = pick(cells, ALIAS.phone).replace(/\D/g, '');
  if (tel.length === 10 || tel.length === 11) tel = CFG.ddiPadrao + tel;
  if (tel.length < 12 || tel.length > 15) erros.push('número inválido: "' + pick(cells, ALIAS.phone) + '"');
  p.phone = tel;

  // pipeline / etapa
  const pipeNome = pick(cells, ALIAS.pipeline) || CFG.pipelinePadrao;
  const etapaNome = pick(cells, ALIAS.etapa) || CFG.etapaPadrao;
  let pipe = null, col = null;
  if (!pipeNome) erros.push('pipeline vazia');
  else {
    const m = pipelines.filter(x => norm(x.name) === norm(pipeNome));
    if (m.length === 0) erros.push('pipeline "' + pipeNome + '" não existe (disponíveis: ' + pipelines.map(x => x.name).join(' | ') + ')');
    else if (m.length > 1) erros.push('pipeline "' + pipeNome + '" está duplicada no CRM');
    else pipe = m[0];
  }
  if (!etapaNome) erros.push('etapa vazia');
  else if (pipe) {
    const m = (pipe.columns || []).filter(x => norm(x.title) === norm(etapaNome));
    if (m.length === 0) erros.push('etapa "' + etapaNome + '" não existe na pipeline "' + pipe.name + '" (disponíveis: ' + (pipe.columns || []).map(x => x.title).join(' | ') + ')');
    else if (m.length > 1) erros.push('etapa "' + etapaNome + '" duplicada na pipeline');
    else col = m[0];
  }
  if (pipe) p.pipelineId = pipe.id;
  if (col) p.columnId = col.id;

  // responsável / criador
  let u = pick(cells, ALIAS.user) || CFG.userIdPadrao;
  if (u !== '' && !isNaN(Number(u))) u = String(Math.trunc(Number(u)));
  if (!u) erros.push('atendente vinculado vazio');
  p.userId = u;

  // opcionais
  const email = pick(cells, ALIAS.email); if (email) p.email = email;
  const empresa = pick(cells, ALIAS.empresa); if (empresa) p.contactCompany = empresa;

  // tags (separe várias com ; ou |)
  const tagNomes = pick(cells, ALIAS.tag).split(/[;|\n]/).map(s => s.trim()).filter(Boolean);
  const tagIds = [];
  for (const t of tagNomes) {
    const m = tags.filter(x => norm(x.label) === norm(t));
    if (m.length === 0) erros.push('tag "' + t + '" não existe');
    else if (m.length > 1) erros.push('tag "' + t + '" duplicada no CRM');
    else if (!tagIds.includes(m[0].id)) tagIds.push(m[0].id);
  }
  if (tagIds.length) p.tagIds = tagIds;

  // motivo de perda (opcional)
  const motivo = pick(cells, ALIAS.motivo);
  if (motivo) p.lossReasons = motivo.split(/[;|]/).map(s => s.trim()).filter(Boolean);

  // campos personalizados: qualquer coluna extra cujo nome seja igual a um campo do CRM
  const cf = [];
  for (const [h, v] of Object.entries(cells)) {
    if (usados.has(h) || v === '') continue;
    const campo = camposAtivos.find(c => norm(c.name) === h);
    if (!campo) { ignoradas.add(h); continue; }
    const t = campo.type;
    let val = v;
    if (t === 'number') { val = Number(String(v).replace(',', '.')); if (Number.isNaN(val)) { erros.push('campo "' + campo.name + '": "' + v + '" não é número'); continue; } }
    else if (t === 'boolean') {
      if (/^(true|sim|s|1|yes|verdadeiro)$/i.test(norm(v))) val = true;
      else if (/^(false|nao|n|0|no|falso)$/i.test(norm(v))) val = false;
      else { erros.push('campo "' + campo.name + '": "' + v + '" não é sim/não'); continue; }
    } else if (t === 'date') {
      let m;
      if ((m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/))) val = m[1] + '-' + m[2] + '-' + m[3];
      else if ((m = String(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) val = m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
      else { erros.push('campo "' + campo.name + '": data "' + v + '" inválida (use AAAA-MM-DD ou DD/MM/AAAA)'); continue; }
    } else if (t === 'single_choice') {
      const o = (campo.options || []).find(x => norm(x) === norm(v));
      if (!o) { erros.push('campo "' + campo.name + '": opção "' + v + '" não existe (' + (campo.options || []).join(' | ') + ')'); continue; }
      val = o;
    } else if (t === 'multiple_choice') {
      const lista = String(v).split(/[;|]/).map(s => s.trim()).filter(Boolean);
      const res = [];
      for (const x of lista) {
        const o = (campo.options || []).find(y => norm(y) === norm(x));
        if (!o) { erros.push('campo "' + campo.name + '": opção "' + x + '" não existe'); } else res.push(o);
      }
      val = res;
    }
    cf.push({ fieldId: campo.id, value: val });
  }
  if (cf.length) p.customFields = cf;

  // duplicadas dentro do próprio arquivo
  if (CFG.bloquearDuplicadasNoArquivo && !erros.length) {
    const chave = [p.phone, p.pipelineId, p.columnId, norm(p.contactName), (p.tagIds || []).join(','), JSON.stringify(p.customFields || [])].join('|');
    if (vistos.has(chave)) erros.push('linha duplicada (igual à linha ' + vistos.get(chave) + ')');
    else vistos.set(chave, _linha);
  }

  out.push({ json: { _linha, nome: p.contactName, numero: p.phone, _acao: erros.length ? 'erro' : (dryRun ? 'simulado' : 'criar'), _erro: erros.join('; '), p, _ignoradas: [...ignoradas] } });
}
return out;

// Junta os dados do ticket (node getTicket + Set) com a linha validada e monta o corpo do POST /opportunities
const ticket = $json;
const row = $('Validar').item.json;
const p = row.p;
const payload = {
  ticketRef: String(ticket.ticketRef ?? '').trim(),
  userId: p.userId,
  contactName: p.contactName,
  phone: p.phone,
  pipelineId: p.pipelineId,
  columnId: p.columnId,
};
for (const k of ['email', 'contactCompany', 'tagIds', 'customFields', 'lossReasons']) if (p[k] !== undefined) payload[k] = p[k];
return { json: { payload, _linha: row._linha, nome: row.nome, numero: row.numero, contactId: ticket.contactId ?? '' } };

// Interpreta a resposta do CRM para cada linha
const ctx = $('Montar payload').item.json;
const code = Number($json.statusCode);
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
let status = 'erro', mensagem = '', id = '';
if (code === 201) { status = 'criado'; id = (body && body.id) || ''; }
else {
  const base = body && (body.message || body.error || body.code);
  mensagem = 'HTTP ' + code + ': ' + (base ? (typeof base === 'string' ? base : JSON.stringify(base)) : JSON.stringify(body)).slice(0, 400);
  if (!ctx.payload.ticketRef) mensagem = 'ticketRef vazio — o node getTicket não devolveu o ticket (' + mensagem + ')';
  if (code === 429) mensagem += ' (limite de 100 req/min atingido — reenvie estas linhas)';
}
return { json: { linha: ctx._linha, nome: ctx.nome, numero: ctx.numero, status, id, contactId: ctx.contactId, ticketRef: ctx.payload.ticketRef, mensagem } };

// Linhas que não vão para o CRM: com erro de validação ou simuladas (modo "apenas validar")
const j = $json;
return { json: { linha: j._linha, nome: j.nome, numero: j.numero, status: j._acao === 'simulado' ? 'simulado' : 'erro', id: '', contactId: '', ticketRef: '', mensagem: j._erro || '' } };

// Consolida o resultado e guarda para o site consultar em /importar-crm-status
const job = $('Criar job').first().json;
const todas = $('Validar').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const porLinha = new Map(res.map(r => [r.linha, r]));
const detalhes = [];
for (const r of todas) {
  const x = porLinha.get(r._linha);
  detalhes.push(x || { linha: r._linha, nome: r.nome, numero: r.numero, status: 'erro', id: '', contactId: '', ticketRef: '', mensagem: 'o node getTicket não devolveu nada para este número (ative "Always Output Data" nele)' });
}
detalhes.sort((a, b) => a.linha - b.linha);
const cont = (s) => detalhes.filter(d => d.status === s).length;
const resumo = {
  status: 'concluido', jobId: job.jobId, dryRun: job.dryRun,
  total: detalhes.length, criados: cont('criado'), erros: cont('erro'), simulados: cont('simulado'),
  colunasIgnoradas: todas.length ? (todas[0]._ignoradas || []) : [],
  finalizadoEm: new Date().toISOString(),
  detalhes: detalhes.slice(0, 5000),
};
const sd = $getWorkflowStaticData('global');
sd.jobs = sd.jobs || {};
sd.jobs[job.jobId] = resumo;
const limite = Date.now() - 48 * 3600 * 1000;
for (const [k, v] of Object.entries(sd.jobs)) if (new Date(v.finalizadoEm).getTime() < limite) delete sd.jobs[k];
return [{ json: { jobId: job.jobId, total: resumo.total, criados: resumo.criados, erros: resumo.erros, simulados: resumo.simulados } }];

const id = ($input.first().json.query || {}).jobId;
const sd = $getWorkflowStaticData('global');
const job = id && sd.jobs ? sd.jobs[id] : null;
return [{ json: job || { status: 'processando', jobId: id || null } }];
